#nullable enable // autogenerated

using System.Linq;
using MVZ2.Audios;
using PVZEngine;
using PVZEngine.Tools;
using PVZEngine.Tools.Random;
using UnityEngine;

namespace MVZ2.ResourcePacks
{
    public class ResourcePackSoundSource : ISoundSource
    {
        public ResourcePackSoundSource(ResourcePackSoundSample[] samples)
        {
            this.samples = samples;
        }
        public NamespaceID? GetRandomSamplePath()
        {
            var count = samples.Length;
            if (count <= 0)
                return null;
            float totalWeight = samples.Select(s => s.weight).Sum();
            float value = Random.Range(0, totalWeight);
            return samples.WeightedRandom(s => s.weight, value).path;
        }

        public int GetMaxCount()
        {
            return maxCount;
        }

        public int GetPriority()
        {
            return priority;
        }

        public float GetLoopPitchStart()
        {
            return loopPitchStart;
        }

        public float GetLoopPitchEnd()
        {
            return loopPitchEnd;
        }

        public float GetLoopVolume()
        {
            return loopVolume;
        }

        public float GetLoopFadeInSpeed()
        {
            return loopFadeInSpeed;
        }

        public float GetLoopFadeOutSpeed()
        {
            return loopFadeOutSpeed;
        }
        public ResourcePackSoundSample[] samples;
        public int maxCount;
        public int priority;
        public float loopPitchStart;
        public float loopPitchEnd;
        public float loopVolume;
        public float loopFadeInSpeed;
        public float loopFadeOutSpeed;
    }
}
